/// `ac.valueOf("P" + id)`.
pub fn country(id: i32) -> Option<&'static CountryInfo> {
    usize::try_from(id).ok().and_then(|i| COUNTRIES.get(i))
}

/// `ac.valueOf("P" + id).gg()`; the game would throw for an unknown id.
pub fn confederation(id: i32) -> i32 {
    country(id).map(|c| c.confederation).unwrap_or(-1)
}

/// The RGB of a flag color table of `best.aq`.
pub fn flag_color(table: &str) -> [u8; 3] {
    match table {
        "qA" => [237, 202, 63],
        "qB" => [225, 225, 0],
        "qC" => [255, 255, 128],
        "qk" => [255, 255, 255],
        "ql" => [0, 0, 0],
        "qm" => [215, 0, 0],
        "qn" => [153, 0, 0],
        "qo" => [241, 10, 33],
        "qq" => [0, 0, 98],
        "qr" => [38, 57, 106],
        "qs" => [5, 49, 122],
        "qt" => [51, 99, 156],
        "qu" => [8, 81, 164],
        "qv" => [51, 168, 205],
        "qw" => [51, 51, 0],
        "qy" => [20, 92, 20],
        "qz" => [2, 108, 62],
        _ => [0, 0, 0],
    }
}
